/**
 * Cari zona JNE dari berbagai sumber data.
 * Urutan prioritas: DEST code > kode pos > kecamatan+kota
 */
export function lookupJneZona(opts: {
  destCode?: string;
  zipCode?: string;
  kecamatan?: string;
  kota?: string;
}): "A" | "B" | "C" | "D" | null {
  if (opts.destCode) {
    const z = JNE_ZONA_BY_DEST[opts.destCode.toUpperCase()];
    if (z) return z;
  }
  if (opts.zipCode) {
    const z = JNE_ZONA_BY_ZIP[opts.zipCode.trim()];
    if (z) return z;
  }
  if (opts.kecamatan && opts.kota) {
    const key = opts.kecamatan.toLowerCase().trim() + "|" + opts.kota.toLowerCase().trim();
    const z = JNE_ZONA_BY_KEC[key];
    if (z) return z;
  }
  return null;
}
